void FMeshContactGenerator::ProcessGeneratedContacts(const FRigidTransform3& ConvexTransform, const FRigidTransform3& MeshToConvexTransform)
{
	if (Contacts.Num() == 0)
	{
		return;
	}

	if (!!Settings.bFixNormals)
	{
		// Contacts that get pruned or corrected will show as green
		DebugDrawContacts(ConvexTransform, FColor::Green, 0.5);
	}

	PruneAndCorrectContacts();

	// Final contacts will be red
	DebugDrawContacts(ConvexTransform, FColor::Red, 1.0);

	// Visited triangles are white, ignored triangles are gray
	DebugDrawTriangles(ConvexTransform, FColor::White, FColor::Silver);

	if (!!Settings.bSortByPhi)
	{
		SortContactByPhi();
	}

	if (!!Settings.bSortForSolverConvergence)
	{
		SortContactsForSolverConvergence();
	}

	FinalizeContacts(MeshToConvexTransform);
}

void FMeshContactGenerator::RemoveDisabledContacts()
{
	// @todo(chaos): don't do this if we have not disabled any contacts

	// Re-pack the contact point array without re-ordering
	const int32 NumContactPoints = Contacts.Num();
	int32 DestContactIndex = 0;		// Index to where the next enabled item goes
	int32 SrcContactIndex = 0;		// Index to the next enabled item
	while (SrcContactIndex < NumContactPoints)
	{
		if (!ContactDatas[SrcContactIndex].IsEnabled())
		{
			// Find the next enabled point index to use as the copy source
			while (++SrcContactIndex < NumContactPoints)
			{
				if (ContactDatas[SrcContactIndex].IsEnabled())
				{
					break;
				}
			}

			if (SrcContactIndex == NumContactPoints)
			{
				break;
			}
		}

		// If we have removed elements, copy source to dest
		if (DestContactIndex != SrcContactIndex)
		{
			Contacts[DestContactIndex] = Contacts[SrcContactIndex];
			ContactDatas[DestContactIndex] = ContactDatas[SrcContactIndex];
		}

		++DestContactIndex;
		++SrcContactIndex;
	}

	// Clip the array to the enabled set
	Contacts.SetNum(DestContactIndex, EAllowShrinking::No);
	ContactDatas.SetNum(DestContactIndex, EAllowShrinking::No);
}

void FMeshContactGenerator::FinalizeContacts(const FRigidTransform3& MeshToConvexTransform)
{
	for (int32 ContactIndex = 0; ContactIndex < Contacts.Num(); ++ContactIndex)
	{
		FContactPoint& ContactPoint = Contacts[ContactIndex];

		ContactPoint.ShapeContactPoints[1] = MeshToConvexTransform.InverseTransformPositionNoScale(ContactPoint.ShapeContactPoints[1]);
		ContactPoint.ShapeContactNormal = MeshToConvexTransform.InverseTransformVectorNoScale(ContactPoint.ShapeContactNormal);
	}
}

inline void SetOneShotManifoldContacts(const TArrayView<const FContactPoint>& ContactPoints)
{
	ResetActiveManifoldContacts();

	FReal MinPhi = TNumericLimits<FReal>::Max();

	int32 NumContacts = ContactPoints.Num();

	// If we have too many manifold points, clip the array. This is considered and error but
	// is important for avoiding OOM or massive slowdowns when something goes wrong
	const int32 MaxManifoldPoints = Chaos_Collision_MaxManifoldPoints;
	if ((MaxManifoldPoints >= 0) && (NumContacts > MaxManifoldPoints))
	{
		NumContacts = MaxManifoldPoints;
		LogOneShotManifoldError(MaxManifoldPoints, ContactPoints);
	}

	ManifoldPoints.Reserve(NumContacts);

	for (int32 ContactIndex = 0; ContactIndex < NumContacts; ++ContactIndex)
	{
		const FContactPoint& ContactPoint = ContactPoints[ContactIndex];
		if (ContactPoint.Phi < CullDistance)
		{
			int32 ManifoldPointIndex = AddManifoldPoint(ContactPoint);
			if (ContactPoint.Phi < MinPhi)
			{
				ClosestManifoldPointIndex = ManifoldPointIndex;
				MinPhi = ContactPoint.Phi;
			}
		}
	}

inline int32 AddManifoldPoint(const FContactPointf& ContactPoint)
{
	int32 ManifoldPointIndex = ManifoldPoints.AddUninitialized();	// Note: no initialization (see InitManifoldPoint)
	InitManifoldPoint(ManifoldPointIndex, ContactPoint);
	return ManifoldPointIndex;
}

// Maximum number of manifold points per contact (-1 for unlimited)
int32 Chaos_Collision_MaxManifoldPoints = -1;
FAutoConsoleVariableRef CVarChaos_Collision_MaxManifoldPoints(TEXT("p.Chaos.Collision.MaxManifoldPoints"), Chaos_Collision_MaxManifoldPoints, TEXT(""));

	template<typename U>
	TContactPoint(const TContactPoint<U>& Other)
		: ShapeContactPoints{ TVec3<FRealType>(Other.ShapeContactPoints[0]), TVec3<FRealType>(Other.ShapeContactPoints[1]) }
		, ShapeContactNormal{ TVec3<FRealType>(Other.ShapeContactNormal) }
		, Phi(FRealType(Other.Phi))
		, FaceIndex(Other.FaceIndex)
		, ContactType(Other.ContactType)
	{
	}

	// Whether the contact point has been set up with contact data
	bool IsSet() const 
	{ 
		return (Phi != InvalidPhi<FRealType>());
	}
};

// Explicit types of TContactPoint for float and double. We should use the float version whenever the contacts are in shape-relative
// space, which is most of the time (some collision functions may choose to generate world-space contacts which are later converted
// to local space, and they should therefore use the double version until the local-space conversion).
using FContactPoint = TContactPoint<FReal>;
using FContactPointf = TContactPoint<FRealSingle>;

virtual const FAABB3 BoundingBox() const override
{
	FAABB3 Box = FAABB3(MSegment.BoundingBox());
	Box.Thicken(GetRadiusf());
	return Box;
}
